   769	  event.priority = VELAWEAR_PRIORITY_NORMAL;
   770	  event.timestamp = (uint32_t)k_uptime_get_32();
   771	  event.data.ble_state.connected = connected;
   772	  if (connected)
   773	    {
   774	      strncpy(event.data.ble_state.device_name, "BLE controller",
   775	              sizeof(event.data.ble_state.device_name) - 1);
