#!/usr/bin/env python3
"""VelaWear BLE to cloud-LLM bridge.

The SF32LB52 side has no IP transport in this MVP. This process keeps the API
key on the host, receives compact requests over BLE, calls an
OpenAI-compatible HTTPS Chat Completions endpoint, and writes the correlated
response back to the board.
"""

from __future__ import annotations

import argparse
import asyncio
import json
import logging
import os
import ssl
import sys
import urllib.error
import urllib.request
from dataclasses import dataclass
from typing import Any, Optional, Tuple


SERVICE_UUID = "12345678-9abc-def0-1234-56789abcdef0"
LLM_REQUEST_UUID = "1234567e-9abc-def0-1234-56789abcdef0"
LLM_RESPONSE_UUID = "1234567f-9abc-def0-1234-56789abcdef0"
AGENT_COMMAND_UUID = "1234567c-9abc-def0-1234-56789abcdef0"

PROTOCOL_VERSION = 1
AGENT_SHOW_REMINDER = 3
LLM_REQUEST_TYPE = 1
LLM_RESPONSE_TYPE = 2
LLM_TEXT_MAX = 220
LLM_REQUEST_HEADER_SIZE = 6
LLM_RESPONSE_HEADER_SIZE = 7
LLM_STATUS_OK = 0
LLM_STATUS_ERROR = 1

DEFAULT_ADDRESS = "CD:AB:78:56:34:12"
DEFAULT_BASE_URL = "https://api.openai.com/v1/chat/completions"
DEFAULT_MODEL = "gpt-4o-mini"


class BridgeError(RuntimeError):
    """Expected bridge or cloud failure that should trigger board fallback."""


@dataclass(frozen=True)
class BridgeConfig:
    address: str
    api_key: str
    base_url: str
    model: str
    http_timeout: float
    connect_timeout: float
    system_prompt: str
    trigger_sequence: int = 1


def load_config(environ: Optional[dict[str, str]] = None) -> BridgeConfig:
    env = os.environ if environ is None else environ
    api_key = env.get("VELAWEAR_LLM_API_KEY", "") or env.get("OPENAI_API_KEY", "")
    return BridgeConfig(
        address=env.get("VELAWEAR_BLE_ADDRESS", DEFAULT_ADDRESS),
        api_key=api_key,
        base_url=env.get("VELAWEAR_LLM_BASE_URL", DEFAULT_BASE_URL),
        model=env.get("VELAWEAR_LLM_MODEL", DEFAULT_MODEL),
        http_timeout=float(env.get("VELAWEAR_LLM_HTTP_TIMEOUT", "12")),
        connect_timeout=float(env.get("VELAWEAR_BLE_CONNECT_TIMEOUT", "15")),
        system_prompt=env.get(
            "VELAWEAR_LLM_SYSTEM_PROMPT",
            "你是 VelaWear 的健康提醒助手。回答简短、具体、适合穿戴设备显示。",
        ),
        trigger_sequence=int(
            env.get("VELAWEAR_AGENT_TRIGGER_SEQUENCE", "1"), 0
        ),
    )


def _bounded_utf8(text: str, maximum: int = LLM_TEXT_MAX) -> bytes:
    encoded = text.encode("utf-8", errors="replace")
    if len(encoded) <= maximum:
        return encoded
    return encoded[:maximum].decode("utf-8", errors="ignore").encode("utf-8")


def encode_llm_response(sequence: int, status: int, text: str = "") -> bytes:
    if not 0 <= sequence <= 0xFFFF:
        raise ValueError("sequence out of range")
    if status not in (LLM_STATUS_OK, LLM_STATUS_ERROR):
        raise ValueError("invalid LLM status")
    payload = _bounded_utf8(text)
    return bytes(
        (
            PROTOCOL_VERSION,
            LLM_RESPONSE_TYPE,
            sequence & 0xFF,
            (sequence >> 8) & 0xFF,
            status,
            len(payload) & 0xFF,
            (len(payload) >> 8) & 0xFF,
        )
    ) + payload


def encode_agent_command(sequence: int, command_id: int, argument: int = 0) -> bytes:
    if not 0 <= sequence <= 0xFFFF:
        raise ValueError("sequence out of range")
    if not 0 <= command_id <= 0xFF:
        raise ValueError("command id out of range")
    if not 0 <= argument <= 0xFFFF:
        raise ValueError("argument out of range")
    return bytes(
        (
            PROTOCOL_VERSION,
            command_id,
            sequence & 0xFF,
            (sequence >> 8) & 0xFF,
            argument & 0xFF,
            (argument >> 8) & 0xFF,
        )
    )


def decode_llm_request(frame: bytes) -> Tuple[int, str]:
    if len(frame) < LLM_REQUEST_HEADER_SIZE:
        raise BridgeError("short LLM request")
    if frame[0] != PROTOCOL_VERSION or frame[1] != LLM_REQUEST_TYPE:
        raise BridgeError("invalid LLM request header")
    sequence = frame[2] | (frame[3] << 8)
    length = frame[4] | (frame[5] << 8)
    if length > LLM_TEXT_MAX or len(frame) != LLM_REQUEST_HEADER_SIZE + length:
        raise BridgeError("invalid LLM request length")
    try:
        prompt = frame[LLM_REQUEST_HEADER_SIZE:].decode("utf-8")
    except UnicodeDecodeError as exc:
        raise BridgeError("invalid UTF-8 prompt") from exc
    if not prompt:
        raise BridgeError("empty LLM prompt")
    return sequence, prompt


def _extract_text(payload: Any) -> str:
    choices = payload.get("choices")
    if not isinstance(choices, list) or not choices:
        raise BridgeError("cloud response has no choices")
    message = choices[0].get("message")
    if not isinstance(message, dict):
        raise BridgeError("cloud response has no message")
    content = message.get("content")
    if isinstance(content, str):
        result = content.strip()
    elif isinstance(content, list):
        parts = []
        for item in content:
            if isinstance(item, dict) and isinstance(item.get("text"), str):
                parts.append(item["text"])
        result = "".join(parts).strip()
    else:
        result = ""
    if not result:
        raise BridgeError("cloud response has empty content")
    return result


def build_cloud_request(config: BridgeConfig, prompt: str) -> bytes:
    if not config.api_key:
        raise BridgeError("VELAWEAR_LLM_API_KEY or OPENAI_API_KEY is not set")
    if not config.base_url or not config.model:
        raise BridgeError("cloud endpoint or model is not configured")
    body = {
        "model": config.model,
        "messages": [
            {"role": "system", "content": config.system_prompt},
            {"role": "user", "content": prompt},
        ],
        "temperature": 0.2,
    }
    return json.dumps(body, ensure_ascii=False).encode("utf-8")


def call_cloud(config: BridgeConfig, prompt: str) -> str:
    request = urllib.request.Request(
        config.base_url,
        data=build_cloud_request(config, prompt),
        headers={
            "Authorization": f"Bearer {config.api_key}",
            "Content-Type": "application/json",
            "Accept": "application/json",
        },
        method="POST",
    )
    try:
        with urllib.request.urlopen(
            request,
            timeout=config.http_timeout,
            context=ssl.create_default_context(),
        ) as stream:
            if stream.status < 200 or stream.status >= 300:
                raise BridgeError(f"cloud HTTP status {stream.status}")
            raw = stream.read(1024 * 1024)
    except urllib.error.HTTPError as exc:
        raise BridgeError(f"cloud HTTP status {exc.code}") from exc
    except (urllib.error.URLError, TimeoutError, OSError) as exc:
        raise BridgeError(f"cloud transport {type(exc).__name__}") from exc

    try:
        payload = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise BridgeError("cloud response is not JSON") from exc
    return _extract_text(payload)


async def _find_device(scanner: Any, address: str, timeout: float) -> Any:
    devices = await scanner.discover(timeout=timeout)
    wanted = address.casefold()
    for device in devices:
        if getattr(device, "address", "").casefold() == wanted:
            return device
    return None


async def serve_once(
    config: BridgeConfig, logger: logging.Logger, trigger_reminder: bool = False
) -> None:
    stage = "import_bleak"
    try:
        from bleak import BleakClient, BleakScanner
    except ImportError as exc:
        raise BridgeError("Bleak is required: python -m pip install bleak") from exc

