            BleakScanner, config.address, config.connect_timeout
        )
        if device is None:
            raise BridgeError(f"BLE device not found: {config.address}")
        logger.info("device_found=true address=%s", config.address)

        queue: asyncio.Queue[bytes] = asyncio.Queue(maxsize=1)

        def on_request(_: Any, data: bytearray) -> None:
            try:
                queue.put_nowait(bytes(data))
            except asyncio.QueueFull:
                logger.warning("LLM request dropped: bridge is busy")

